(()=>{function mount(){const join=document.getElementById('join');if(!join||document.getElementById('guardian-wall-gateway'))return;const hans=document.documentElement.lang==='zh-Hans';const t=hans?{title:'从阅读出发，让守护被听见',intro:'新闻、庭讯、案件与制度观察，带你找到可查阅的公共记录；也欢迎把关心与建议留在守护留言墙。',wall:'守护留言墙',wallIntro:'来自不同地区的关心与建议，经审核后成为持续对话的一部分。',read:'进入专区',write:'留下你的观点',all:'查看精选留言墙',href:'https://cn.globalprotectionwall.com/?region=hk&lang=zh-Hans#guest-message',items:[['最新消息','追踪儿童保护相关的公开资讯与行动。'],['庭讯与旁听','依程序阅读可查阅的法院与旁听记录。'],['案件记录','从事件脉络理解需要被持续追问的责任。'],['制度观察','从公开资料一起检视保护制度的缺口。'],['历史案件','让制度记忆成为今天的提醒。'],['加入行动','从阅读、留言到参与，让关心走得更远。']],voices:[['家长关心','希望学校与社区能建立更完整的通报与支持机制。'],['教育现场','孩子说出口时，能有一个愿意倾听、愿意接住的人。'],['公民倡议','每一件案件的关注，都是推动制度往前走的力量。']]}:{title:'從閱讀出發，讓守護被聽見',intro:'新聞、庭訊、案件與制度觀察，帶你找到可查閱的公共紀錄；也歡迎把關心與建議留在守護留言牆。',wall:'守護留言牆',wallIntro:'來自不同地區的關心與建議，經審核後成為持續對話的一部分。',read:'進入專區',write:'留下你的觀點',all:'查看精選留言牆',href:'https://global-protection.jerryzuhow77.chatgpt.site/?region=tw&lang=zh-Hant#guest-message',items:[['最新消息','追蹤兒少保護相關的公開資訊與行動。'],['庭訊與旁聽','依程序閱讀可查閱的法院與旁聽紀錄。'],['案件紀錄','從事件脈絡理解需要被持續追問的責任。'],['制度觀察','從公開資料一起檢視保護制度的缺口。'],['歷史案件','讓制度記憶成為今天的提醒。'],['加入行動','從閱讀、留言到參與，讓關心走得更遠。']],voices:[['家長關心','希望學校與社區能建立更完整的通報與支持機制。'],['教育現場','孩子說出口時，能有一個願意傾聽、願意接住的人。'],['公民倡議','每一件案件的關注，都是推動制度往前走的力量。']]};const routes=['./news/','./hearing-records/','./cases/','#home-special-features','./historical-cases/','#join'];const cards=t.items.map((x,i)=>'<a class="gmc" href="'+routes[i]+'"><b>0'+(i+1)+'</b><strong>'+x[0]+'</strong><span>'+x[1]+'</span><em>'+t.read+' →</em></a>').join('');const voices=t.voices.map(x=>'<article><small>'+x[0]+'</small><p>「'+x[1]+'」</p></article>').join('');const section=document.createElement('section');section.className='home-section gwg';section.id='guardian-wall-gateway';section.innerHTML='<header><small>READING MAP · GUARDIAN VOICES</small><h2>'+t.title+'</h2><p>'+t.intro+'</p></header><div class="gwg-layout"><div class="gmc-grid">'+cards+'</div><aside><i>✦</i><h3>'+t.wall+'</h3><p>'+t.wallIntro+'</p><div class="voices">'+voices+'</div><a class="button" href="'+t.href+'">'+t.write+' →</a><a class="more" href="'+t.href.replace('#guest-message','#featured-messages')+'">'+t.all+' →</a></aside></div>';join.before(section);const style=document.createElement('style');style.textContent='.gwg{margin:72px 0 40px;padding:42px 0;border-block:1px solid var(--line,#cfc3af);background:linear-gradient(90deg,rgba(232,238,232,.36),rgba(247,240,229,.15))}.gwg header{max-width:760px;margin:0 auto 30px;text-align:center}.gwg header small{font-size:11px;letter-spacing:.16em;color:#834d36;font-weight:700}.gwg h2{margin:10px 0 8px;font-size:32px;color:#173f40}.gwg header p{margin:0;line-height:1.9;color:#5c5a54}.gwg-layout{display:grid;grid-template-columns:1.55fr .72fr;gap:28px}.gmc-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.gmc{display:flex;min-height:174px;flex-direction:column;padding:18px;text-decoration:none;color:inherit;border:1px solid #cfc3af;background:rgba(255,252,245,.82);box-shadow:0 8px 20px rgba(77,69,53,.06)}.gmc:hover{transform:translateY(-3px)}.gmc b{font-size:11px;color:#a95f43}.gmc strong{margin:12px 0 7px;font-size:20px;color:#173f40}.gmc span{font-size:13px;line-height:1.7;color:#65615a}.gmc em{margin-top:auto;padding-top:13px;font-style:normal;font-size:12px;color:#834d36}.gwg aside{padding:27px 24px;border:1px solid #cfc3af;background:linear-gradient(160deg,#fffaf0,#edf2ec)}.gwg aside i{display:inline-flex;width:32px;height:32px;align-items:center;justify-content:center;border-radius:50%;background:#285b59;color:#fff;font-style:normal}.gwg h3{margin:11px 0 5px;font-size:25px;color:#173f40}.gwg aside>p{margin:0 0 16px;font-size:13px;line-height:1.75;color:#5c5a54}.voices{display:grid;gap:9px;margin-bottom:16px}.voices article{padding:10px 12px;border-left:3px solid #91aaa4;background:rgba(255,255,255,.58)}.voices article:nth-child(2){border-color:#c78567}.voices small{color:#7a5b46;font-weight:700}.voices p{margin:4px 0 0;font-size:12px;line-height:1.6}.gwg .button{display:flex;justify-content:center;margin-bottom:12px}.more{display:block;text-align:center;color:#5c5a54;font-size:13px;text-decoration:none}@media(max-width:900px){.gwg-layout{grid-template-columns:1fr}.gmc-grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:560px){.gwg{margin:42px 0 28px;padding:28px 0}.gwg h2{font-size:25px}.gmc-grid{grid-template-columns:1fr}.gmc{min-height:142px}}';document.head.append(style)}document.readyState==='loading'?document.addEventListener('DOMContentLoaded',mount):mount()})();